   const body={type:websiteEdit.type,id:websiteEdit.id};
   if(revision.snapshotId)body.snapshotId=revision.snapshotId;
   else body.revisionId=revision.revisionId;
   const data=await gatewayRequest("/api/communications/website/restore",{method:"POST",body:JSON.stringify(body)});
   setWebsiteEdit(data.item||null);
   await loadWebsiteContent(websiteType);
   if(data.item)await loadWebsiteRevisions(data.item.type,data.item.id);
